// Build-time values are generated by vite.config.ts. Only public app files belong here.
importScripts('/push-worker.js');
const PREFIX='class-portal-shell-';
const CACHE=PREFIX+'__PWA_VERSION__';
const PRECACHE=/* PWA_ASSETS */[];
const ICONS=new Set(['/icon-180.png','/icon-192.png','/icon-512.png','/manifest.webmanifest']);
const isAsset=path=>/^\/assets\/[^/]+\.(?:js|css|woff2?|png|svg)$/.test(path)||ICONS.has(path);

self.addEventListener('install',event=>{
  // Cache the matching HTML and hashed bundles together before declaring an update ready.
  event.waitUntil((async()=>{
    try{
      const cache=await caches.open(CACHE);
      await cache.addAll(PRECACHE.map(url=>new Request(url,{cache:'reload',credentials:'omit'})));
    }catch(error){
      await caches.delete(CACHE);
      throw error;
    }
  })());
});

self.addEventListener('activate',event=>{
  event.waitUntil((async()=>{
    const own=(await caches.keys()).filter(name=>name.startsWith(PREFIX));
    // Retain the immediately previous shell for another open tab finishing its work.
    const previous=own.filter(name=>name!==CACHE).at(-1);
    await Promise.all(own.filter(name=>name!==CACHE&&name!==previous).map(name=>caches.delete(name)));
    await self.clients.claim();
  })());
});

self.addEventListener('message',event=>{
  if(event.data?.type==='APPLY_UPDATE')event.waitUntil(self.skipWaiting());
});

self.addEventListener('fetch',event=>{
  const request=event.request,url=new URL(request.url);
  // Firebase Auth helpers, API calls, credentials and non-GET requests never enter Cache Storage.
  if(request.method!=='GET'||url.origin!==self.location.origin||request.headers.has('Authorization')||url.search)return;
  if(request.mode==='navigate'&&(url.pathname==='/'||url.pathname==='/index.html')){
    event.respondWith((async()=>{
      const cache=await caches.open(CACHE);
      try{
        const response=await fetch(request);
        if(response.ok)return response;
        return await cache.match('/')||response;
      }catch{
        return await cache.match('/')||new Response('인터넷에 연결한 뒤 다시 열어 주세요.',{status:503,headers:{'Content-Type':'text/plain; charset=utf-8'}});
      }
    })());
    return;
  }
  if(!isAsset(url.pathname))return;
  event.respondWith((async()=>{
    const cache=await caches.open(CACHE),cached=await cache.match(request);
    if(cached)return cached;
    const response=await fetch(request);
    if(response.ok&&response.type==='basic')await cache.put(request,response.clone());
    return response;
  })());
});
